import React, { useState } from "react";
import { View, Text } from "react-native";
import { SkeuoCheckbox } from "../skeuo-checkbox";
import { useSkeuo } from "../theme";
export function HabitList({ value, onValueChange }: {value?:string[];onValueChange?:(value:string[])=>void}) {
  const { colors: c } = useSkeuo();
  const [localDone, setLocalDone] = useState<string[]>(["A little movement"]);
  const done = value ?? localDone;
  const setDone = (next:string[]) => { setLocalDone(next); onValueChange?.(next); };
  const labels = [
    "A little movement",
    "Read ten pages",
    "Make something",
    "Get outside",
  ];
  return (
    <View style={{ gap: 12 }}>
      <Text
        accessibilityLiveRegion="polite"
        style={{ color: c.muted, fontSize: 12 }}
      >
        {done.length} of {labels.length} complete today
      </Text>
      {labels.map((label) => (
        <SkeuoCheckbox
          key={label}
          label={label}
          checked={done.includes(label)}
          onCheckedChange={(checked) =>
            setDone(checked ? [...done,label] : done.filter(item=>item!==label))
          }
        />
      ))}
    </View>
  );
}

import { StyleSheet, Text, View } from "react-native";
import * as Checkbox from "@rn-primitives/checkbox";
import { useSkeuo, useFeedback } from "./theme";
import { styles } from "./styles";
import type { ToggleProps } from "./types";
import { SkeuoText } from "./skeuo-text";
export function SkeuoCheckbox({
  label,
  checked,
  onCheckedChange,
  disabled,
}: ToggleProps) {
  const { colors } = useSkeuo();
  const feedback = useFeedback();
  return (
    <Checkbox.Root
      accessibilityLabel={label}
      checked={checked}
      disabled={disabled}
      onCheckedChange={(v) => {
        feedback();
        onCheckedChange(v);
      }}
      style={StyleSheet.flatten([
        styles.row,
        styles.touch,
        { opacity: disabled ? 0.45 : 1 },
      ])}
    >
      <View
        style={[
          styles.check,
          {
            backgroundColor: checked ? colors.accent : colors.well,
            borderColor: colors.edge,
          },
        ]}
      >
        <Checkbox.Indicator>
          <Text style={{ color: colors.accentInk, fontWeight: "700" }}>✓</Text>
        </Checkbox.Indicator>
      </View>
      <View style={styles.label}>
        <SkeuoText>{label}</SkeuoText>
      </View>
    </Checkbox.Root>
  );
}

import React, { useState, useRef } from "react";
import { Image, Text, View } from "react-native";
import { SkeuoButton } from "./skeuo-button";
import { useSkeuo } from "./theme";
export type PhotoItem = { uri: string; title: string; caption?: string };
export function SkeuoPhotoCarousel({
  items,
  label = "Photo collection",
}: {
  items: PhotoItem[];
  label?: string;
}) {
  const { colors: c } = useSkeuo();
  const [position, setPosition] = useState(0);
  const touch = useRef({x:0,y:0});
  const index = Math.min(position, Math.max(0, items.length - 1));
  const item = items[index];
  if (!item) return <Text style={{ color: c.muted }}>No photos yet.</Text>;
  return (
    <View accessibilityLabel={label} style={{ gap: 20, paddingTop: 16 }}>
      <View onTouchStart={event => { touch.current = {x:event.nativeEvent.pageX,y:event.nativeEvent.pageY}; }} onTouchEnd={event => { const dx=event.nativeEvent.pageX-touch.current.x; const dy=event.nativeEvent.pageY-touch.current.y; if(Math.abs(dx)>40 && Math.abs(dx)>Math.abs(dy)) setPosition(Math.max(0,Math.min(items.length-1,index+(dx<0?1:-1)))); }} style={{ height: 244, marginHorizontal: 20 }}>
        {[-7, 5].map((rotation, i) => (
          <View
            key={rotation}
            style={{
              position: "absolute",
              inset: 0,
              backgroundColor: c.surface,
              borderWidth: 1,
              borderColor: c.edge,
              borderRadius: 3,
              transform: [{ rotate: `${rotation}deg` }],
              margin: 6 + i * 2,
            }}
          />
        ))}
        <View
          style={{
            flex: 1,
            padding: 10,
            paddingBottom: 16,
            backgroundColor: c.raised,
            borderWidth: 1,
            borderColor: c.edge,
            borderBottomWidth: 3,
            gap: 8,
          }}
        >
          <Image
            source={{ uri: item.uri }}
            accessibilityLabel={item.title}
            alt={item.title}
            resizeMode="cover"
            style={{ flex: 1, backgroundColor: c.well }}
          />
          <Text style={{ color: c.ink, fontSize: 15, fontWeight: "600" }}>
            {item.title}
          </Text>
        </View>
      </View>
      <View
        style={{
          flexDirection: "row",
          justifyContent: "space-between",
          alignItems: "center",
          gap: 12,
        }}
      >
        <SkeuoButton
          accessibilityLabel="Previous photo"
          disabled={index === 0}
          onPress={() => setPosition(index - 1)}
        >
          ‹
        </SkeuoButton>
        <Text
          accessibilityLiveRegion="polite"
          style={{ color: c.muted, fontSize: 12 }}
        >
          {index + 1} / {items.length}
        </Text>
        <SkeuoButton
          accessibilityLabel="Next photo"
          disabled={index === items.length - 1}
          onPress={() => setPosition(index + 1)}
        >
          ›
        </SkeuoButton>
      </View>
      {item.caption && (
        <Text style={{ color: c.muted, fontSize: 13, lineHeight: 20 }}>
          {item.caption}
        </Text>
      )}
    </View>
  );
}
